        public void RefreshProject()
        {
            CommitInstance(); _library.Clear(); _flow.Clear(); FctStudioProject project = _getProject(); if (project == null) return;
            Dictionary<string, int> libraryOrders = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (FunctionBlockDefinition block in project.Blocks)
            {
                string group = FlowLibraryRow.GetLibraryGroup(block);
                int libraryOrder; libraryOrders.TryGetValue(group, out libraryOrder); libraryOrder++; libraryOrders[group] = libraryOrder;
                IEnumerable<FunctionBlockDefinition> children = string.Equals(block.ModuleKind, "Custom", StringComparison.OrdinalIgnoreCase) ? (block.Steps ?? new List<BlockStepDefinition>()).Where(step => step.IsModuleReference).Select(step => project.Blocks.FirstOrDefault(candidate => candidate.Id == step.ReferencedBlockId)).Where(value => value != null).GroupBy(value => value.Id, StringComparer.Ordinal).Select(group => group.First()) : Enumerable.Empty<FunctionBlockDefinition>();
                _library.Add(new FlowLibraryRow(block, libraryOrder, children));
            }
            if (_domainFilter != null) { _domainFilter.ItemsSource = new[] { "全部模块" }.Concat(_library.Select(item => item.Block.Category).Distinct().OrderBy(value => value)).ToArray(); _domainFilter.SelectedIndex = 0; }
            int order = 0; foreach (FlowBlockInstance instance in project.Flow) { if (instance.Snapshot != null && string.IsNullOrWhiteSpace(instance.DisplayName)) instance.DisplayName = instance.Snapshot.Name; _flow.Add(new FlowInstanceRow(instance, ++order)); }
            _summary.Text = "当前流程：  " + project.Flow.Count + " 个功能块实例";
            RefreshLibraryViews(); if (_flow.Count > 0) _flowList.SelectedIndex = 0; else { _selectedInstance = null; _parameters.Clear(); _expanded.Clear(); }
        }

        public void UpdateDebugStep(int sequenceIndex, string status, string result)
        {
            if (_lastCompile == null) return;
            CompiledStepTrace trace = _lastCompile.Trace.FirstOrDefault(item => item.SequenceIndex == sequenceIndex);
            if (trace == null) return;
            string key = trace.FlowInstanceId + ":" + trace.BlockStepId; _debugStatuses[key] = status ?? string.Empty; _debugResults[key] = result ?? string.Empty;
            FlowExpandedStepRow row = _expanded.FirstOrDefault(item => item.Instance.Id == trace.FlowInstanceId && item.Step.Id == trace.BlockStepId); if (row != null) { row.Status = status; row.Result = result; if (status == "运行中") { _expandedGrid.SelectedItem = row; _expandedGrid.ScrollIntoView(row); } }
            FlowInstanceRow instanceRow = _flow.FirstOrDefault(item => item.Instance.Id == trace.FlowInstanceId); if (instanceRow == null) return; if (status == "运行中") { if (!string.IsNullOrWhiteSpace(_activeFlowInstanceId) && _activeFlowInstanceId != trace.FlowInstanceId) { FlowInstanceRow previous = _flow.FirstOrDefault(item => item.Instance.Id == _activeFlowInstanceId); if (previous != null && previous.RuntimeStatus == "运行中") previous.SetRuntimeStatus("完成"); } _activeFlowInstanceId = trace.FlowInstanceId; instanceRow.SetRuntimeStatus("运行中"); _flowList.SelectedItem = instanceRow; _flowList.ScrollIntoView(instanceRow); }
            else if (status == "失败") { instanceRow.SetRuntimeStatus("失败"); _activeFlowInstanceId = trace.FlowInstanceId; _flowList.SelectedItem = instanceRow; _flowList.ScrollIntoView(instanceRow); }
            else if (status == "完成") { CompiledStepTrace last = _lastCompile.Trace.Where(item => item.FlowInstanceId == trace.FlowInstanceId).OrderBy(item => item.SequenceIndex).LastOrDefault(); if (last != null && last.BlockStepId == trace.BlockStepId) { instanceRow.SetRuntimeStatus("完成"); if (_activeFlowInstanceId == trace.FlowInstanceId) _activeFlowInstanceId = null; } }
        }

        public void UpdateRuntimeVariables(string snapshot)
        {
            if (_runtimeVariables != null) _runtimeVariables.Text = "运行变量：" + (string.IsNullOrWhiteSpace(snapshot) ? "{}" : snapshot);
        }
