        private static DataGrid QuickGrid(System.Collections.IEnumerable source) { return new DataGrid { ItemsSource = source, AutoGenerateColumns = false, CanUserAddRows = false, HeadersVisibility = DataGridHeadersVisibility.Column, Margin = new Thickness(0), GridLinesVisibility = DataGridGridLinesVisibility.Horizontal, RowHeight = double.NaN, MinRowHeight = 38, ColumnHeaderHeight = 36, BorderBrush = BorderColor(), SelectionMode = DataGridSelectionMode.Extended, SelectionUnit = DataGridSelectionUnit.FullRow, HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalAlignment = HorizontalAlignment.Stretch, HorizontalContentAlignment = HorizontalAlignment.Stretch, FontSize = 12.5, MinColumnWidth = 80 }; }
        private static Style ParameterTextStyle(bool centered) { Style style = new Style(typeof(TextBlock)); style.Setters.Add(new Setter(TextBlock.TextWrappingProperty, TextWrapping.Wrap)); style.Setters.Add(new Setter(TextBlock.TextTrimmingProperty, TextTrimming.None)); style.Setters.Add(new Setter(TextBlock.VerticalAlignmentProperty, VerticalAlignment.Center)); style.Setters.Add(new Setter(TextBlock.HorizontalAlignmentProperty, HorizontalAlignment.Stretch)); style.Setters.Add(new Setter(TextBlock.TextAlignmentProperty, centered ? TextAlignment.Center : TextAlignment.Left)); style.Setters.Add(new Setter(TextBlock.MarginProperty, new Thickness(8, 7, 8, 7))); return style; }
        private static GroupStyle CollapsibleParameterGroupStyle() { FrameworkElementFactory expander = new FrameworkElementFactory(typeof(Expander)); expander.SetValue(Expander.IsExpandedProperty, false); expander.SetValue(Expander.MarginProperty, new Thickness(0, 4, 0, 4)); expander.SetValue(Expander.HorizontalAlignmentProperty, HorizontalAlignment.Stretch); expander.SetValue(Expander.HorizontalContentAlignmentProperty, HorizontalAlignment.Stretch); expander.SetBinding(Expander.HeaderProperty, new Binding("Name")); FrameworkElementFactory header = new FrameworkElementFactory(typeof(Border)); header.SetValue(Border.BackgroundProperty, new SolidColorBrush(Color.FromRgb(239, 246, 255))); header.SetValue(Border.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(205, 221, 243))); header.SetValue(Border.BorderThicknessProperty, new Thickness(1)); header.SetValue(Border.CornerRadiusProperty, new CornerRadius(4)); header.SetValue(Border.PaddingProperty, new Thickness(12, 8, 12, 8)); header.SetValue(Border.HorizontalAlignmentProperty, HorizontalAlignment.Stretch); FrameworkElementFactory title = new FrameworkElementFactory(typeof(TextBlock)); title.SetBinding(TextBlock.TextProperty, new Binding()); title.SetValue(TextBlock.FontSizeProperty, 13d); title.SetValue(TextBlock.FontWeightProperty, FontWeights.SemiBold); title.SetValue(TextBlock.TextWrappingProperty, TextWrapping.Wrap); title.SetValue(TextBlock.ForegroundProperty, new SolidColorBrush(Color.FromRgb(30, 91, 170))); header.AppendChild(title); expander.SetValue(Expander.HeaderTemplateProperty, new DataTemplate { VisualTree = header }); FrameworkElementFactory presenter = new FrameworkElementFactory(typeof(ItemsPresenter)); presenter.SetValue(ItemsPresenter.MarginProperty, new Thickness(6, 3, 0, 5)); presenter.SetValue(ItemsPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Stretch); expander.AppendChild(presenter); ControlTemplate template = new ControlTemplate(typeof(GroupItem)) { VisualTree = expander }; Style container = new Style(typeof(GroupItem)); container.Setters.Add(new Setter(GroupItem.TemplateProperty, template)); container.Setters.Add(new Setter(GroupItem.HorizontalContentAlignmentProperty, HorizontalAlignment.Stretch)); return new GroupStyle { ContainerStyle = container }; }
        private UIElement BuildQuickParameterPanel(DataGrid grid, bool limitPage)
        {
            Grid root = new Grid { Margin = new Thickness(8, 5, 8, 5) };
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(36) });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            DockPanel toolbar = new DockPanel { Margin = new Thickness(0, 0, 0, 5) };
            StackPanel actions = new StackPanel { Orientation = Orientation.Horizontal };
            DockPanel.SetDock(actions, Dock.Right);
            if (!limitPage) actions.Children.Add(Button("应用选中修改", ApplySelectedQuickParameters_Click));
            actions.Children.Add(PrimaryButton("应用本页修改", Apply_Click));
            toolbar.Children.Add(actions);
            TextBox search; Grid quickSearchHost = SearchHost(limitPage ? "搜索测试项 / LIMIT" : "搜索模块 / 参数", out search, QuickSearch_TextChanged, true); if (limitPage) _limitSearch = search; else _quickSearch = search; quickSearchHost.Width = 210; quickSearchHost.HorizontalAlignment = HorizontalAlignment.Left; quickSearchHost.Margin = new Thickness(0, 1, 8, 1); toolbar.Children.Add(quickSearchHost); TextBlock scopeHint = new TextBlock { Text = limitPage ? "修改当前流程实例的判断条件；Ctrl+S保存SEQ" : "只修改当前引用实例，不改变标准模块默认值；Ctrl+S保存SEQ", Foreground = TextSecondary(), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 8, 0), TextTrimming = TextTrimming.CharacterEllipsis }; toolbar.Children.Add(scopeHint);
            root.Children.Add(toolbar);
            Grid.SetRow(grid, 1); root.Children.Add(grid);
            return root;
        }

        private void QuickSearch_TextChanged(object sender, TextChangedEventArgs e) { TextBox search = sender as TextBox; if (search == null) return; DataGrid grid = ReferenceEquals(search, _limitSearch) ? _limitGrid : _parameterGrid; if (grid == null) return; ICollectionView view = CollectionViewSource.GetDefaultView(grid.ItemsSource); string keyword = Convert.ToBoolean(search.Tag ?? false) ? string.Empty : (search.Text ?? string.Empty).Trim(); view.Filter = item => { FlowQuickParameterRow row = item as FlowQuickParameterRow; return row != null && (ReferenceEquals(grid, _limitGrid) ? row.IsLimit : row.IsSetting) && (keyword.Length == 0 || row.SearchText.IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0); }; view.Refresh(); }
        private void ApplySelectedQuickParameters_Click(object sender, RoutedEventArgs e)
        {
            _parameterGrid.CommitEdit(DataGridEditingUnit.Cell, true); _parameterGrid.CommitEdit(DataGridEditingUnit.Row, true);
            IEnumerable<FlowQuickParameterRow> rows = _parameterGrid.SelectedItems.Cast<object>().OfType<FlowQuickParameterRow>();
            if (!rows.Any() && _parameterGrid.SelectedItem is FlowQuickParameterRow) rows = new[] { (FlowQuickParameterRow)_parameterGrid.SelectedItem };
            foreach (FlowQuickParameterRow row in rows) row.Apply();
            CommitInstance(); LoadInstance(); _changed();
        }

        private void CreateCustomModule_Click(object sender, RoutedEventArgs e)
        {
            FctStudioProject project = _getProject();
            FunctionBlockDefinition block = new FunctionBlockDefinition { Name = "新功能块", Category = "自定义", ModuleKind = "Custom", IsStandard = false, Version = "1.0" };
            FunctionBlockPropertiesWindow dialog = new FunctionBlockPropertiesWindow(block, new[] { project == null ? string.Empty : project.Product }) { Owner = Window.GetWindow(this) };
            if (dialog.ShowDialog() != true) return;
            dialog.ApplyTo(block); project.Blocks.Add(block); _changed(); RefreshProject(); _openBlockEditor(block);
        }

        private void FlowSearchChanged(object sender, TextChangedEventArgs e)
        {
            if (_flowList == null || _flowSearch == null) return;
            string keyword = Convert.ToBoolean(_flowSearch.Tag ?? false) ? string.Empty : (_flowSearch.Text ?? string.Empty).Trim();
            ICollectionView view = CollectionViewSource.GetDefaultView(_flowList.ItemsSource);
            view.Filter = item => { FlowInstanceRow row = item as FlowInstanceRow; return row != null && (keyword.Length == 0 || (row.Name + " " + row.Phase + " " + row.Products + " " + row.Status).IndexOf(keyword, StringComparison.OrdinalIgnoreCase) >= 0); };
            view.Refresh();
        }

