        private void AddBlock_Click(object sender, RoutedEventArgs e) { FlowLibraryRow row = SelectedLibraryRow(); if (row != null) InsertLibraryBlock(row, _flow.Count); }
        private void InsertLibraryBlock(FlowLibraryRow row, int index) { if (row == null) return; index = Math.Max(0, Math.Min(index, _flow.Count)); FunctionBlockDefinition snapshot = row.Block.Clone(); FlowBlockInstance instance = new FlowBlockInstance { BlockId = row.Block.Id, DisplayName = row.Block.Name, Snapshot = snapshot, Phase = PhaseFor(row.Block) }; foreach (BlockParameterDefinition parameter in snapshot.Parameters) instance.ParameterOverrides[parameter.Name] = parameter.DefaultValue; _getProject().Flow.Insert(index, instance); FlowInstanceRow item = new FlowInstanceRow(instance, index + 1); _flow.Insert(index, item); RefreshFlowOrders(); _flowList.SelectedItem = item; _flowList.ScrollIntoView(item); _summary.Text = "当前流程：  " + _flow.Count + " 个功能块实例"; _changed(); }
        private void LibraryPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e) { _libraryDragArmed = false; _libraryDragItem = null; if (StudioDragDropGuard.IsMultiSelectGesture || FindAncestor<ScrollBar>(e.OriginalSource as DependencyObject) != null || FindAncestor<Thumb>(e.OriginalSource as DependencyObject) != null || FindAncestor<ToggleButton>(e.OriginalSource as DependencyObject) != null) return; ListBoxItem item = FindAncestor<ListBoxItem>(e.OriginalSource as DependencyObject); if (item == null) return; item.IsSelected = true; _libraryDragItem = item.DataContext as FlowLibraryRow ?? item.Content as FlowLibraryRow; if (_libraryDragItem == null) return; _libraryDragStart = e.GetPosition(_libraryList); _libraryDragArmed = true; }
        private void LibraryPreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs e) { _libraryDragArmed = false; _libraryDragItem = null; }
        private void LibraryPreviewMouseMove(object sender, MouseEventArgs e) { if (!_libraryDragArmed || _libraryDragItem == null || e.LeftButton != MouseButtonState.Pressed) return; Point current = e.GetPosition(_libraryList); if (!StudioDragDropGuard.HasMovedEnough(_libraryDragStart, current)) return; FlowLibraryRow row = _libraryDragItem; _libraryDragArmed = false; _libraryDragItem = null; DragDrop.DoDragDrop(_libraryList, new DataObject(typeof(FlowLibraryRow), row), DragDropEffects.Copy); }
        private void FlowList_DragOver(object sender, DragEventArgs e) { bool library = e.Data.GetDataPresent(typeof(FlowLibraryRow)), moving = e.Data.GetDataPresent(typeof(FlowInstanceRow)); if (!library && !moving) { e.Effects = DragDropEffects.None; ClearFlowDropTarget(); e.Handled = true; return; } e.Effects = moving ? DragDropEffects.Move : DragDropEffects.Copy; DataGridRow target = FindAncestor<DataGridRow>(e.OriginalSource as DependencyObject); ShowFlowDropTarget(target); _summary.Text = target == null ? "释放鼠标：放到流程末尾" : "释放鼠标：放到第 " + (target.GetIndex() + 1).ToString(CultureInfo.InvariantCulture) + " 行之前"; e.Handled = true; }
        private void FlowList_DragLeave(object sender, DragEventArgs e) { ClearFlowDropTarget(); RestoreFlowSummary(); }
