        private void FlowList_Drop(object sender, DragEventArgs e) { DataGridRow target = FindAncestor<DataGridRow>(e.OriginalSource as DependencyObject); int index = target == null ? _flow.Count : target.GetIndex(); ClearFlowDropTarget(); FlowInstanceRow moving = e.Data.GetData(typeof(FlowInstanceRow)) as FlowInstanceRow; if (moving != null) { int oldIndex = _flow.IndexOf(moving); if (oldIndex >= 0) { if (oldIndex < index) index--; index = Math.Max(0, Math.Min(_flow.Count - 1, index)); if (index != oldIndex) { FlowBlockInstance instance = moving.Instance; _getProject().Flow.RemoveAt(oldIndex); _getProject().Flow.Insert(index, instance); _flow.Move(oldIndex, index); RefreshFlowOrders(); _flowList.SelectedItem = moving; _flowList.ScrollIntoView(moving); _changed(); } } RestoreFlowSummary(); e.Handled = true; return; } FlowLibraryRow row = e.Data.GetData(typeof(FlowLibraryRow)) as FlowLibraryRow; if (row != null) InsertLibraryBlock(row, index); RestoreFlowSummary(); e.Handled = true; }
