        internal bool OpenSelectedFlowForEditing()
        {
            FlowInstanceRow row = _flowList == null ? null : _flowList.SelectedItem as FlowInstanceRow;
            FlowBlockInstance instance = row == null ? _selectedInstance : row.Instance;
            if (instance == null || _openBlockEditor == null) return false;
            if (_selectedInstance != instance) { _flowList.SelectedItem = row; _selectedInstance = instance; LoadInstance(); }
            CommitInstance();
            FctStudioProject project = _getProject();
            FunctionBlockDefinition source = project == null ? null : project.Blocks.FirstOrDefault(block => block.Id == instance.BlockId);
            if (source == null && instance.Snapshot != null && project != null)
            {
                source = instance.Snapshot.Clone(); source.Id = instance.BlockId; project.Blocks.Add(source); _changed();
            }
            if (source == null) return false;
            _openBlockEditor(source); return true;
        }
