        private static T FindAncestor<T>(DependencyObject source) where T : DependencyObject { DependencyObject current = source; while (current != null && !(current is T)) current = VisualTreeHelper.GetParent(current); return current as T; }
        private void LoadInstance()
        {
            _parameters.Clear(); _quickParameters.Clear(); _expanded.Clear();
            if (_selectedInstance == null || _selectedInstance.Snapshot == null) { if (_instanceNameBox != null) _instanceNameBox.Text = string.Empty; return; }
            if (string.IsNullOrWhiteSpace(_selectedInstance.Phase)) _selectedInstance.Phase = PhaseFor(_selectedInstance.Snapshot); _instanceNameBox.Text = _selectedInstance.DisplayName;
            foreach (BlockParameterDefinition parameter in _selectedInstance.Snapshot.Parameters) { object value; if (!_selectedInstance.ParameterOverrides.TryGetValue(parameter.Name, out value)) value = parameter.DefaultValue; FlowParameterRow row = new FlowParameterRow(parameter, value); _parameters.Add(row); _quickParameters.Add(FlowQuickParameterRow.ForBlockParameter(row)); }
            int referenceNumber = 0;
            foreach (BlockStepDefinition step in _selectedInstance.Snapshot.Steps.Where(value => value.Enabled))
            {
                if (step.IsModuleReference)
                {
                    referenceNumber++;
                    FunctionBlockDefinition referenced = _getProject().Blocks.FirstOrDefault(value => value.Id == step.ReferencedBlockId);
                    if (referenced != null) { string groupName = ReferenceParameterGroupName(referenceNumber, referenced, step); foreach (BlockParameterDefinition parameter in referenced.Parameters ?? new List<BlockParameterDefinition>()) { object value; if (!step.ReferencedParameterOverrides.TryGetValue(parameter.Name, out value)) value = parameter.DefaultValue; _quickParameters.Add(FlowQuickParameterRow.ForReferencedModule(step, referenced, parameter, value, groupName)); } }
                    continue;
                }
                if (new[] { "LowLimit", "HighLimit", "Comtype", "Unit", "Limit" }.Any(step.StepProperties.ContainsKey)) _quickParameters.Add(FlowQuickParameterRow.ForStepLimits(step));
                try { JArray checks = JArray.Parse(Convert.ToString(step.ToStep().Get("SignalChecksJson", "[]"), CultureInfo.InvariantCulture)); for (int index = 0; index < checks.Count; index++) { JObject check = checks[index] as JObject; if (check != null) _quickParameters.Add(FlowQuickParameterRow.ForTableSignalCheck(step, index, check)); } } catch { }
            }
            RefreshExpanded(); if (_quickSearch != null) QuickSearch_TextChanged(this, null);
        }
        private static string ReferenceParameterGroupName(int number, FunctionBlockDefinition module, BlockStepDefinition reference) { List<string> values = new List<string>(); foreach (BlockParameterDefinition parameter in (module.Parameters ?? new List<BlockParameterDefinition>()).Take(3)) { object value; if (!(reference.ReferencedParameterOverrides ?? new Dictionary<string, object>()).TryGetValue(parameter.Name, out value)) value = parameter.DefaultValue; string text = Convert.ToString(value, CultureInfo.InvariantCulture); if (!string.IsNullOrWhiteSpace(text)) values.Add((string.IsNullOrWhiteSpace(parameter.DisplayName) ? parameter.Name : parameter.DisplayName) + "=" + text + (string.IsNullOrWhiteSpace(parameter.Unit) ? string.Empty : parameter.Unit)); } return number.ToString("00", CultureInfo.InvariantCulture) + "  " + module.Name + (values.Count == 0 ? string.Empty : "   ·   " + string.Join("  /  ", values)); }
        private void CommitInstance() { if (_selectedInstance == null) return; string before = FctStudioProjectService.Serialize(_getProject()); _selectedInstance.DisplayName = string.IsNullOrWhiteSpace(_instanceNameBox.Text) ? _selectedInstance.Snapshot.Name : _instanceNameBox.Text.Trim(); if (string.IsNullOrWhiteSpace(_selectedInstance.Phase)) _selectedInstance.Phase = PhaseFor(_selectedInstance.Snapshot); _parameterGrid.CommitEdit(DataGridEditingUnit.Cell, true); _parameterGrid.CommitEdit(DataGridEditingUnit.Row, true); if (_limitGrid != null) { _limitGrid.CommitEdit(DataGridEditingUnit.Cell, true); _limitGrid.CommitEdit(DataGridEditingUnit.Row, true); } foreach (FlowQuickParameterRow row in _quickParameters) row.Apply(); foreach (FlowParameterRow row in _parameters) _selectedInstance.ParameterOverrides[row.Parameter.Name] = row.ConvertValue(); SyncCustomModuleFromCurrentInstance(); foreach (FlowExpandedStepRow row in _expanded) { string key = row.BreakpointKey; if (row.Breakpoint && !_getProject().Breakpoints.Contains(key)) _getProject().Breakpoints.Add(key); if (!row.Breakpoint) _getProject().Breakpoints.Remove(key); } FlowInstanceRow item = _flow.FirstOrDefault(value => value.Instance == _selectedInstance); if (item != null) item.Refresh(); CollectionViewSource.GetDefaultView(_flowList.ItemsSource).Refresh(); if (!string.Equals(before, FctStudioProjectService.Serialize(_getProject()), StringComparison.Ordinal)) _changed(); }
        private void SyncCustomModuleFromCurrentInstance() { if (_selectedInstance == null || _selectedInstance.Snapshot == null) return; FctStudioProject project = _getProject(); FunctionBlockDefinition source = project == null ? null : project.Blocks.FirstOrDefault(block => block.Id == _selectedInstance.BlockId); if (source == null || !string.Equals(source.ModuleKind, "Custom", StringComparison.OrdinalIgnoreCase)) return; source.Name = _selectedInstance.Snapshot.Name; source.Category = _selectedInstance.Snapshot.Category; source.Description = _selectedInstance.Snapshot.Description; source.Version = _selectedInstance.Snapshot.Version; source.Parameters = (_selectedInstance.Snapshot.Parameters ?? new List<BlockParameterDefinition>()).Select(parameter => parameter.Clone()).ToList(); source.Steps = (_selectedInstance.Snapshot.Steps ?? new List<BlockStepDefinition>()).Select(step => step.Clone()).ToList(); source.SupportedProducts = new List<string>(_selectedInstance.Snapshot.SupportedProducts ?? new List<string>()); }
        private void RefreshExpanded() { _expanded.Clear(); if (_selectedInstance == null || _selectedInstance.Snapshot == null) return; int number = 0; AppendExpandedSteps(_selectedInstance.Snapshot, string.Empty, null, new HashSet<string>(StringComparer.Ordinal), ref number); }
        private void AppendExpandedSteps(FunctionBlockDefinition block, string prefix, IDictionary<string, object> referenceValues, ISet<string> stack, ref int number)
        {
            if (block == null || !stack.Add(block.Id)) return;
            foreach (BlockStepDefinition step in block.Steps.Where(value => value.Enabled))
            {
                if (step.IsModuleReference)
                {
                    FunctionBlockDefinition child = _getProject().Blocks.FirstOrDefault(value => value.Id == step.ReferencedBlockId);
                    string childPrefix = string.IsNullOrWhiteSpace(prefix) ? step.ReferencedBlockName : prefix + " / " + step.ReferencedBlockName;
                    AppendExpandedSteps(child, childPrefix, step.ReferencedParameterOverrides, stack, ref number); continue;
                }
                number++; string key = _selectedInstance.Id + ":" + step.Id; string name = step.ToStep().StepName; if (!string.IsNullOrWhiteSpace(prefix)) name = prefix + " / " + name;
                string parameterSummary = referenceValues == null ? null : string.Join(", ", referenceValues.Take(6).Select(pair => pair.Key + "=" + Convert.ToString(pair.Value, CultureInfo.InvariantCulture)));
                FlowExpandedStepRow row = new FlowExpandedStepRow(_selectedInstance, step, number, _getProject().Breakpoints.Contains(key), name, parameterSummary); string status, result; if (_debugStatuses.TryGetValue(key, out status)) row.Status = status; if (_debugResults.TryGetValue(key, out result)) row.Result = result; _expanded.Add(row);
            }
            stack.Remove(block.Id);
        }
        private void CopyInstance_Click(object sender, RoutedEventArgs e) { if (_selectedInstance == null) return; FlowBlockInstance copy = new FlowBlockInstance { BlockId = _selectedInstance.BlockId, DisplayName = _selectedInstance.DisplayName + " - 副本", Phase = _selectedInstance.Phase, PreserveStepNames = _selectedInstance.PreserveStepNames, Snapshot = _selectedInstance.Snapshot.Clone(), ParameterOverrides = new Dictionary<string, object>(_selectedInstance.ParameterOverrides, StringComparer.Ordinal) }; int index = _getProject().Flow.IndexOf(_selectedInstance) + 1; _getProject().Flow.Insert(index, copy); _flow.Insert(index, new FlowInstanceRow(copy, index + 1)); RefreshFlowOrders(); _flowList.SelectedItem = _flow[index]; _changed(); }
        private void DeleteInstance_Click(object sender, RoutedEventArgs e) { if (_selectedInstance == null) return; int index = _getProject().Flow.IndexOf(_selectedInstance); _getProject().Flow.Remove(_selectedInstance); _flow.RemoveAt(index); RefreshFlowOrders(); if (_flow.Count > 0) _flowList.SelectedIndex = Math.Min(index, _flow.Count - 1); _summary.Text = "当前流程：  " + _flow.Count + " 个功能块实例"; _changed(); }
        private void MoveUp_Click(object sender, RoutedEventArgs e) { Move(-1); } private void MoveDown_Click(object sender, RoutedEventArgs e) { Move(1); }
        private void Move(int offset) { if (_selectedInstance == null) return; int oldIndex = _getProject().Flow.IndexOf(_selectedInstance), newIndex = oldIndex + offset; if (newIndex < 0 || newIndex >= _getProject().Flow.Count) return; _getProject().Flow.RemoveAt(oldIndex); _getProject().Flow.Insert(newIndex, _selectedInstance); _flow.Move(oldIndex, newIndex); RefreshFlowOrders(); _flowList.SelectedIndex = newIndex; _changed(); }
