        private void ToggleInstance_Click(object sender, RoutedEventArgs e) { if (_selectedInstance == null) return; _selectedInstance.Enabled = !_selectedInstance.Enabled; FlowInstanceRow row = _flow.First(value => value.Instance == _selectedInstance); row.SetRuntimeStatus(_selectedInstance.Enabled ? "待运行" : "已停用"); row.Refresh(); _changed(); }
        private void SyncInstance_Click(object sender, RoutedEventArgs e) { if (_selectedInstance == null) return; FunctionBlockDefinition source = _getProject().Blocks.FirstOrDefault(block => block.Id == _selectedInstance.BlockId); if (source == null) { MessageBox.Show("功能块库中已找不到该来源，当前流程快照仍可继续使用。", "同步功能块", MessageBoxButton.OK, MessageBoxImage.Information); return; } Dictionary<string, object> oldValues = new Dictionary<string, object>(_selectedInstance.ParameterOverrides, StringComparer.Ordinal); _selectedInstance.Snapshot = source.Clone(); _selectedInstance.ParameterOverrides.Clear(); foreach (BlockParameterDefinition parameter in source.Parameters) { object value; _selectedInstance.ParameterOverrides[parameter.Name] = oldValues.TryGetValue(parameter.Name, out value) ? value : parameter.DefaultValue; } LoadInstance(); FlowInstanceRow row = _flow.First(value => value.Instance == _selectedInstance); row.Refresh(); _changed(); _log("流程实例已同步到功能块 " + source.Name + " V" + source.Version); }
