        private static Border Surface() { return new Border { Background = new SolidColorBrush(Color.FromRgb(251, 252, 254)), BorderBrush = BorderColor(), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(3) }; }
        private static TextBlock Icon(string glyph, double size) { return new TextBlock { Text = glyph, FontFamily = new FontFamily("Segoe MDL2 Assets"), FontSize = size, Foreground = TextSecondary(), VerticalAlignment = VerticalAlignment.Center }; }
        private static Grid SearchHost(string placeholder, out TextBox textBox, TextChangedEventHandler changed, bool managePlaceholder)
        {
            Grid host = new Grid { Margin = new Thickness(10, 1, 10, 4) };
            TextBox box = new TextBox { Text = placeholder, Tag = managePlaceholder, Foreground = TextSecondary(), Padding = new Thickness(26, 4, 7, 4), FontSize = 12, Height = 29, ToolTip = placeholder };
            if (changed != null) box.TextChanged += changed;
            if (managePlaceholder)
            {
                box.GotKeyboardFocus += delegate { if (Convert.ToBoolean(box.Tag ?? false)) { box.Tag = false; box.Text = string.Empty; box.Foreground = TextPrimary(); } };
                box.LostKeyboardFocus += delegate { if (string.IsNullOrWhiteSpace(box.Text)) { box.Tag = true; box.Text = placeholder; box.Foreground = TextSecondary(); } };
            }
            host.Children.Add(box);
            TextBlock icon = Icon("\uE721", 11); icon.Margin = new Thickness(8, 0, 0, 0); icon.HorizontalAlignment = HorizontalAlignment.Left; icon.IsHitTestVisible = false; host.Children.Add(icon);
            textBox = box; return host;
        }
        private static Button SquareToolbarButton(string glyph, string toolTip, RoutedEventHandler handler)
        {
            Button button = Button(string.Empty, handler); button.Width = 20; button.MinWidth = 20; button.Padding = new Thickness(0); button.ToolTip = toolTip; button.Content = Icon(glyph, 11); return button;
        }
        private static TextBlock CountBadge(int value) { return new TextBlock { Text = value.ToString(CultureInfo.InvariantCulture), FontSize = 11, Foreground = TextSecondary(), Background = new SolidColorBrush(Color.FromRgb(244, 247, 251)), Padding = new Thickness(6, 2, 6, 2), Margin = new Thickness(8, 0, 8, 0), VerticalAlignment = VerticalAlignment.Center }; }
        private static Expander LibraryExpander(string glyph, string title, TextBlock count, UIElement content, bool expanded) { DockPanel header = new DockPanel { Margin = new Thickness(6, 8, 4, 8) }; DockPanel.SetDock(count, Dock.Right); header.Children.Add(count); TextBlock icon = Icon(glyph, 13); icon.Margin = new Thickness(0, 0, 10, 0); DockPanel.SetDock(icon, Dock.Left); header.Children.Add(icon); header.Children.Add(new TextBlock { Text = title, FontSize = 13, FontWeight = FontWeights.SemiBold, Foreground = TextPrimary(), VerticalAlignment = VerticalAlignment.Center }); return new Expander { Header = header, Content = content, IsExpanded = expanded, BorderBrush = BorderColor(), BorderThickness = new Thickness(0, 1, 0, 0), Padding = new Thickness(8, 0, 8, 8) }; }
        private static ListBox LibraryList(ICollectionView view)
        {
