        private static string DomainFor(FunctionBlockDefinition block) { if (block == null) return "公共准备"; if (string.Equals(block.ModuleKind, "Custom", StringComparison.OrdinalIgnoreCase)) return "我的模块"; if (block.Category == "主驱") return "主驱"; if (block.Category == "DCDC/辅驱") return "辅驱/DCDC"; if (block.Category == "安全") return "安全收尾"; return "公共准备"; }
        private static string PhaseFor(FunctionBlockDefinition block) { string domain = DomainFor(block); if (domain == "主驱") return "主驱测试"; if (domain == "辅驱/DCDC") return "辅驱测试"; if (domain == "安全收尾") return "安全收尾"; return "准备阶段"; }

