    internal sealed class FlowLibraryRow : INotifyPropertyChanged { private bool _isExpanded; public FlowLibraryRow(FunctionBlockDefinition block, int order = 0, IEnumerable<FunctionBlockDefinition> children = null) { Block = block; Order = order; Children = new ObservableCollection<ModuleTreeChildRow>((children ?? Enumerable.Empty<FunctionBlockDefinition>()).Select(value => new ModuleTreeChildRow(value))); } public FunctionBlockDefinition Block { get; private set; } public ObservableCollection<ModuleTreeChildRow> Children { get; private set; } public bool HasChildren { get { return Children.Count > 0; } } public bool IsExpanded { get { return _isExpanded; } set { if (_isExpanded == value) return; _isExpanded = value; PropertyChangedEventHandler handler = PropertyChanged; if (handler != null) handler(this, new PropertyChangedEventArgs("IsExpanded")); } } public int Order { get; private set; } public string ItemNumber { get { return Order.ToString("00", CultureInfo.InvariantCulture); } } public Visibility StandardVisibility { get { return string.Equals(Block.ModuleKind, "Standard", StringComparison.OrdinalIgnoreCase) ? Visibility.Visible : Visibility.Collapsed; } } public Visibility ProductVisibility { get { return StandardVisibility == Visibility.Visible ? Visibility.Collapsed : Visibility.Visible; } } public string Name { get { return Block.Name; } } public int ActionCount { get { return Block.Steps == null ? 0 : Block.Steps.Count; } } public string DisplayText { get { string products = Block.SupportedProducts == null || Block.SupportedProducts.Count == 0 ? "全部产品" : string.Join("/", Block.SupportedProducts); return Block.Name + "\n" + ActionCount + " 个动作 · " + products; } } public bool IsProductModule { get { return !string.Equals(Block.ModuleKind, "Standard", StringComparison.OrdinalIgnoreCase); } } public string LibraryGroup { get { return GetLibraryGroup(Block); } } public static string GetLibraryGroup(FunctionBlockDefinition block) { return string.Equals(block.ModuleKind, "Standard", StringComparison.OrdinalIgnoreCase) ? "标准模块" : string.Equals(block.ModuleKind, "Product", StringComparison.OrdinalIgnoreCase) ? "产品模块" : "自定义模块"; } public string TreeText { get { return (string.Equals(Block.ModuleKind, "Standard", StringComparison.OrdinalIgnoreCase) ? "标准 - " : string.Equals(Block.ModuleKind, "Product", StringComparison.OrdinalIgnoreCase) ? "产品 - " : string.Empty) + Block.Name; } } public event PropertyChangedEventHandler PropertyChanged; }
    internal sealed class FlowInstanceRow : INotifyPropertyChanged
    {
        private int _order; private string _runtimeStatus = "待运行";
        public FlowInstanceRow(FlowBlockInstance instance, int order = 0) { Instance = instance; _order = order; if (!instance.Enabled) _runtimeStatus = "已停用"; }
        public FlowBlockInstance Instance { get; private set; }
        public bool Enabled { get { return Instance.Enabled; } }
        public string Number { get { return _order.ToString("00", CultureInfo.InvariantCulture); } }
        public void SetOrder(int order) { _order = order; Raise("Number"); }
        public string Name { get { return Instance.DisplayName; } }
        public string Phase { get { return string.IsNullOrWhiteSpace(Instance.Phase) ? "准备阶段" : Instance.Phase; } }
        public int ActionCount { get { return Instance.Snapshot == null ? 0 : Instance.Snapshot.Steps.Count; } }
        public string RuntimeStatus { get { return _runtimeStatus; } }
        public string Status { get { return !Instance.Enabled ? "已停用" : _runtimeStatus == "待运行" ? "已启用" : _runtimeStatus; } }
        public Brush RowTextBrush { get { return Enabled ? new SolidColorBrush(Color.FromRgb(37, 49, 67)) : new SolidColorBrush(Color.FromRgb(132, 143, 158)); } }
        public Brush NumberBackground { get { return Enabled ? new SolidColorBrush(Color.FromRgb(235, 243, 255)) : new SolidColorBrush(Color.FromRgb(221, 225, 231)); } }
        public Brush NumberForeground { get { return Enabled ? new SolidColorBrush(Color.FromRgb(24, 112, 224)) : new SolidColorBrush(Color.FromRgb(126, 137, 151)); } }
        public Brush StatusBrush { get { if (!Enabled) return new SolidColorBrush(Color.FromRgb(139, 149, 162)); return Status == "运行中" ? new SolidColorBrush(Color.FromRgb(0, 154, 108)) : Status == "失败" ? new SolidColorBrush(Color.FromRgb(210, 51, 51)) : Status == "完成" || Status == "已启用" ? new SolidColorBrush(Color.FromRgb(41, 180, 86)) : Status == "已停止" ? new SolidColorBrush(Color.FromRgb(230, 142, 35)) : new SolidColorBrush(Color.FromRgb(94, 123, 160)); } }
        public void SetRuntimeStatus(string status) { _runtimeStatus = status ?? "待运行"; Raise("RuntimeStatus"); Raise("Status"); Raise("StatusBrush"); }
        public string Products { get { return Instance.Snapshot == null || Instance.Snapshot.SupportedProducts == null || Instance.Snapshot.SupportedProducts.Count == 0 ? "全部产品" : string.Join("/", Instance.Snapshot.SupportedProducts); } }
        public string MoreText { get { return "更多 ⌄"; } }
        public string DisplayText { get { return Instance.DisplayName + "\n   " + ActionCount + " 个动作"; } }
        public event PropertyChangedEventHandler PropertyChanged;
        public void Refresh() { foreach (string name in new[] { "DisplayText", "Name", "Phase", "ActionCount", "Status", "StatusBrush", "RuntimeStatus", "Products", "Number", "Enabled", "RowTextBrush", "NumberBackground", "NumberForeground" }) Raise(name); }
        private void Raise(string name) { PropertyChangedEventHandler handler = PropertyChanged; if (handler != null) handler(this, new PropertyChangedEventArgs(name)); }
    }
    internal sealed class FlowParameterRow : INotifyPropertyChanged { private string _valueText; public FlowParameterRow(BlockParameterDefinition parameter, object value) { Parameter = parameter; OriginalType = value == null ? typeof(string) : value.GetType(); _valueText = value == null ? string.Empty : Convert.ToString(value, CultureInfo.InvariantCulture); } public BlockParameterDefinition Parameter { get; private set; } public Type OriginalType { get; private set; } public string DisplayName { get { return string.IsNullOrWhiteSpace(Parameter.DisplayName) ? Parameter.Name : Parameter.DisplayName; } } public string Unit { get { return Parameter.Unit; } } public string Description { get { return Parameter.Description; } } public string ValueText { get { return _valueText; } set { _valueText = value ?? string.Empty; Raise("ValueText"); } } public object ConvertValue() { if (OriginalType == typeof(bool)) return ValueText == "1" || bool.Parse(ValueText); if (OriginalType == typeof(int)) return int.Parse(ValueText, CultureInfo.InvariantCulture); if (OriginalType == typeof(long)) return long.Parse(ValueText, CultureInfo.InvariantCulture); if (OriginalType == typeof(double) || OriginalType == typeof(float) || OriginalType == typeof(decimal)) return double.Parse(ValueText, CultureInfo.InvariantCulture); return ValueText; } public event PropertyChangedEventHandler PropertyChanged; private void Raise(string name) { PropertyChangedEventHandler handler = PropertyChanged; if (handler != null) handler(this, new PropertyChangedEventArgs(name)); } }
    internal sealed class FlowQuickParameterRow : INotifyPropertyChanged
    {
        private readonly FlowParameterRow _parameter; private readonly BlockStepDefinition _step; private readonly BlockParameterDefinition _referencedParameter; private readonly Type _referencedValueType; private readonly int _tableCheckIndex = -1; private string _valueText, _lowLimitText, _highLimitText, _compareText, _unitText, _stringLimitText;
        private FlowQuickParameterRow(FlowParameterRow parameter) { _parameter = parameter; Scope = "模块参数"; GroupName = "当前模块参数"; ParameterDisplayName = parameter.DisplayName; StepName = parameter.DisplayName; Description = parameter.Description; _unitText = parameter.Unit; }
        private FlowQuickParameterRow(BlockStepDefinition step) { _step = step; Scope = "测试判断"; GroupName = step.ToStep().StepName; ParameterDisplayName = step.ToStep().StepName; StepName = step.ToStep().StepName; _lowLimitText = Get("LowLimit"); _highLimitText = Get("HighLimit"); _compareText = Get("Comtype"); _unitText = Get("Unit"); _stringLimitText = Get("Limit"); Description = "一行修改该测试项的全部判断条件"; }
        private FlowQuickParameterRow(BlockStepDefinition step, int index, JObject check) { _step = step; _tableCheckIndex = index; Scope = "整表信号"; GroupName = step.ToStep().StepName; ParameterDisplayName = Convert.ToString(check["Name"], CultureInfo.InvariantCulture); StepName = step.ToStep().StepName + " / " + ParameterDisplayName; _lowLimitText = Convert.ToString(check["LowLimit"], CultureInfo.InvariantCulture); _highLimitText = Convert.ToString(check["HighLimit"], CultureInfo.InvariantCulture); _compareText = Convert.ToString(check["Comtype"], CultureInfo.InvariantCulture); _unitText = Convert.ToString(check["Unit"], CultureInfo.InvariantCulture); _stringLimitText = Convert.ToString(check["Limit"], CultureInfo.InvariantCulture); Description = "整表一次读取后解析并判断该信号"; }
        private FlowQuickParameterRow(BlockStepDefinition step, FunctionBlockDefinition module, BlockParameterDefinition parameter, object value, string groupName) { _step = step; _referencedParameter = parameter; _referencedValueType = value == null ? typeof(string) : value.GetType(); ParameterDisplayName = string.IsNullOrWhiteSpace(parameter.DisplayName) ? parameter.Name : parameter.DisplayName; Scope = IsJudgmentParameter(parameter) ? "引用LIMIT" : "引用参数"; GroupName = groupName; StepName = module.Name + " / " + ParameterDisplayName; _valueText = value == null ? string.Empty : Convert.ToString(value, CultureInfo.InvariantCulture); _unitText = parameter.Unit ?? string.Empty; Description = string.IsNullOrWhiteSpace(parameter.Description) ? "只修改当前引用，不改变标准模块默认值" : parameter.Description; }
        public static FlowQuickParameterRow ForBlockParameter(FlowParameterRow parameter) { return new FlowQuickParameterRow(parameter); }
        public static FlowQuickParameterRow ForStepLimits(BlockStepDefinition step) { return new FlowQuickParameterRow(step); }
        public static FlowQuickParameterRow ForTableSignalCheck(BlockStepDefinition step, int index, JObject check) { return new FlowQuickParameterRow(step, index, check); }
        public static FlowQuickParameterRow ForReferencedModule(BlockStepDefinition step, FunctionBlockDefinition module, BlockParameterDefinition parameter, object value, string groupName) { return new FlowQuickParameterRow(step, module, parameter, value, groupName); }
        public string Scope { get; private set; } public string GroupName { get; private set; } public string ParameterDisplayName { get; private set; } public string StepName { get; private set; } public string Description { get; private set; }
        public bool IsSetting { get { return Scope == "模块参数" || Scope == "引用参数"; } }
        public bool IsLimit { get { return Scope == "测试判断" || Scope == "整表信号" || Scope == "引用LIMIT"; } }
        public string ValueText { get { return _parameter == null ? _valueText ?? string.Empty : _parameter.ValueText; } set { if (_parameter == null) _valueText = value ?? string.Empty; else _parameter.ValueText = value ?? string.Empty; Raise("ValueText"); } }
        public string LowLimitText { get { return _lowLimitText ?? string.Empty; } set { _lowLimitText = value ?? string.Empty; Raise("LowLimitText"); } }
        public string HighLimitText { get { return _highLimitText ?? string.Empty; } set { _highLimitText = value ?? string.Empty; Raise("HighLimitText"); } }
        public string CompareText { get { return _compareText ?? string.Empty; } set { _compareText = value ?? string.Empty; Raise("CompareText"); } }
        public string UnitText { get { return _unitText ?? string.Empty; } set { _unitText = value ?? string.Empty; Raise("UnitText"); } }
        public string StringLimitText { get { return _stringLimitText ?? string.Empty; } set { _stringLimitText = value ?? string.Empty; Raise("StringLimitText"); } }
        public string SearchText { get { return string.Join(" ", new[] { Scope, StepName, ValueText, LowLimitText, HighLimitText, CompareText, UnitText, StringLimitText, Description }); } }
        public void SetField(string field, string value) { switch (field) { case "下限": LowLimitText = value; break; case "上限": HighLimitText = value; break; case "比较方式": CompareText = value; break; case "单位": UnitText = value; break; case "字符串期望值": StringLimitText = value; break; default: ValueText = value; break; } }
        public void Apply() { if (_parameter != null || _step == null) return; if (_referencedParameter != null) { _step.ReferencedParameterOverrides[_referencedParameter.Name] = ConvertReferencedValue(ValueText); return; } if (_tableCheckIndex >= 0) { JArray checks = JArray.Parse(Convert.ToString(_step.ToStep().Get("SignalChecksJson", "[]"), CultureInfo.InvariantCulture)); JObject check = _tableCheckIndex < checks.Count ? checks[_tableCheckIndex] as JObject : null; if (check == null) return; if (check["LowLimit"] != null) check["LowLimit"] = double.Parse(LowLimitText, CultureInfo.InvariantCulture); if (check["HighLimit"] != null) check["HighLimit"] = double.Parse(HighLimitText, CultureInfo.InvariantCulture); check["Comtype"] = CompareText; check["Unit"] = UnitText; check["Limit"] = StringLimitText; _step.StepProperties["SignalChecksJson"] = checks.ToString(Formatting.None); return; } Apply("LowLimit", LowLimitText); Apply("HighLimit", HighLimitText); Apply("Comtype", CompareText); Apply("Unit", UnitText); Apply("Limit", StringLimitText); }
        private object ConvertReferencedValue(string text) { if (_referencedValueType == typeof(bool)) return text == "1" || bool.Parse(text); if (_referencedValueType == typeof(int) || _referencedValueType == typeof(short) || _referencedValueType == typeof(long)) return int.Parse(text, CultureInfo.InvariantCulture); if (_referencedValueType == typeof(double) || _referencedValueType == typeof(float) || _referencedValueType == typeof(decimal)) return double.Parse(text, CultureInfo.InvariantCulture); return text ?? string.Empty; }
        private static bool IsJudgmentParameter(BlockParameterDefinition parameter) { string text = ((parameter == null ? string.Empty : parameter.Name) + " " + (parameter == null ? string.Empty : parameter.DisplayName)).ToLowerInvariant(); return text.Contains("limit") || text.Contains("low") || text.Contains("high") || text.Contains("expected") || text.Contains("imbalance") || text.Contains("compare") || text.Contains("comtype") || text.Contains("下限") || text.Contains("上限") || text.Contains("期望") || text.Contains("允许") || text.Contains("不平衡") || text.Contains("比较"); }
        private string Get(string key) { object value; return _step.StepProperties.TryGetValue(key, out value) ? Convert.ToString(value, CultureInfo.InvariantCulture) ?? string.Empty : string.Empty; }
        private void Apply(string key, string text) { if (!_step.StepProperties.ContainsKey(key) && string.IsNullOrWhiteSpace(text)) return; object original; if (_step.StepProperties.TryGetValue(key, out original) && (original is double || original is float || original is decimal)) _step.StepProperties[key] = double.Parse(text, CultureInfo.InvariantCulture); else if (original is int) _step.StepProperties[key] = int.Parse(text, CultureInfo.InvariantCulture); else _step.StepProperties[key] = text ?? string.Empty; }
        public event PropertyChangedEventHandler PropertyChanged; private void Raise(string name) { PropertyChangedEventHandler handler = PropertyChanged; if (handler != null) handler(this, new PropertyChangedEventArgs(name)); }
    }
    internal sealed class FlowExpandedStepRow : INotifyPropertyChanged { private bool _breakpoint; private string _status = "待运行"; private string _result = string.Empty; private readonly string _displayName; private readonly string _parameterSummary; public FlowExpandedStepRow(FlowBlockInstance instance, BlockStepDefinition step, int number, bool breakpoint, string displayName = null, string parameterSummary = null) { Instance = instance; Step = step; Number = number; _breakpoint = breakpoint; _displayName = displayName; _parameterSummary = parameterSummary; } public FlowBlockInstance Instance { get; private set; } public BlockStepDefinition Step { get; private set; } public int Number { get; private set; } public string StepName { get { return string.IsNullOrWhiteSpace(_displayName) ? (Step.IsModuleReference ? Step.ReferencedBlockName : Step.ToStep().StepName) : _displayName; } } public string FunctionName { get { return Step.IsModuleReference ? "模块引用" : Step.ToStep().FunctionName; } } public string ParameterSummary { get { if (!string.IsNullOrWhiteSpace(_parameterSummary)) return _parameterSummary; return Step.IsModuleReference ? string.Join(", ", Step.ReferencedParameterOverrides.Take(6).Select(pair => pair.Key + "=" + Convert.ToString(pair.Value, CultureInfo.InvariantCulture))) : string.Join(", ", Step.ToStep().Parameters.Take(4).Select(pair => pair.Key + "=" + Convert.ToString(pair.Value, CultureInfo.InvariantCulture))); } } public string BreakpointKey { get { return Instance.Id + ":" + Step.Id; } } public bool Breakpoint { get { return _breakpoint; } set { if (_breakpoint == value) return; _breakpoint = value; Raise("Breakpoint"); Raise("BreakpointGlyph"); Raise("BreakpointBrush"); } } public string BreakpointGlyph { get { return _breakpoint ? "●" : "○"; } } public Brush BreakpointBrush { get { return _breakpoint ? new SolidColorBrush(Color.FromRgb(220, 42, 42)) : new SolidColorBrush(Color.FromRgb(188, 198, 212)); } } public string Status { get { return _status; } set { _status = value ?? string.Empty; Raise("Status"); } } public string Result { get { return _result; } set { _result = value ?? string.Empty; Raise("Result"); } } public event PropertyChangedEventHandler PropertyChanged; private void Raise(string name) { PropertyChangedEventHandler handler = PropertyChanged; if (handler != null) handler(this, new PropertyChangedEventArgs(name)); } }
